def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    total_my_def = sum(1 for h in history if h[0] == 'D')
    total_op_def = sum(1 for h in history if h[1] == 'D')

    window = min(10, n)
    recent_op_def = sum(1 for h in history[-window:] if h[1] == 'D')
    recent_my_def = sum(1 for h in history[-window:] if h[0] == 'D')

    # Exploit mode: opponent not retaliating to our recent defections
    if recent_op_def == 0 and recent_my_def > 0:
        return 'D'

    # Probe: if we have never defected and opponent has not defected recently
    if total_my_def == 0 and recent_op_def == 0 and n >= 15:
        return 'D'

    # If opponent never defected and we have defected, exploit
    if total_op_def == 0 and total_my_def > 0:
        return 'D'

    # Now some defections have occurred
    op_coop_rate = (n - total_op_def) / n

    if op_coop_rate > 0.7:
        my_last = history[-1][0]
        op_last = history[-1][1]
        if op_last == 'D' and my_last == 'C' and rng.random() < 0.2:
            return 'D'
        return 'C'
    elif op_coop_rate < 0.3:
        return 'D'
    else:
        my_last = history[-1][0]
        op_last = history[-1][1]
        if my_last == 'D' and op_last == 'C':
            return 'D'
        if my_last == 'C' and op_last == 'D':
            return 'D'
        if my_last == 'D' and op_last == 'D':
            return 'C'
        return 'C'
